                                                                                                                                                                                                                                                                                                                                                                            self.goals_status_label = tk.Label(goal_controls_frame, text="Goals: Active",
                                                                                                                                                                                                                                                                                                                                                                            bg='#374151', fg='#10B981', font=('Arial', 9))
